/* ============================================================
   LIVRET DES RÈGLES — Niveau Excellence (Certificat 900-1000 points)
   Inventaire : liste officielle Vuibert / Le Grand Livre de
   l'orthographe (D. Dumas). Explications rédigées pour ce projet.
   ============================================================ */
window.RULES_EXC = [

  /* ---------- Formes verbales ---------- */
  { n:"R69", th:"verbe", t:"accourir et le redoublement du r",
    e:"Comme courir : un seul r au présent (il accourt), deux r au futur et au conditionnel (il accourra, ils accourraient)." },
  { n:"R70", th:"verbe", t:"agonir et agoniser",
    e:"Agonir = accabler : il m'a agoni d'injures. Agoniser = être mourant. On conjugue agonir comme finir : ils m'agonissent d'injures." },
  { n:"R55", th:"verbe", t:"asseoir : la question du e",
    e:"Deux conjugaisons : je m'assieds, il s'assied, ils s'asseyent ou je m'assois, il s'assoit, ils s'assoient. Futur : je m'assiérai ou je m'assoirai. Le e de l'infinitif disparaît des formes conjuguées : il s'assoit, et non « il s'asseoit »." },
  { n:"R58", th:"verbe", t:"avoir et être au subjonctif (nous, vous)",
    e:"Que nous ayons, que vous ayez (sans i) ; que nous soyons, que vous soyez (sans i). N'écrivez pas « que nous ayions » ni « soyions »." },
  { n:"R91-4", th:"verbe", t:"béni et bénit",
    e:"Bénit, bénite : réservé aux choses consacrées par un rite religieux (eau bénite, pain bénit, cierge bénit). Partout ailleurs, et toujours après l'auxiliaire avoir : béni, bénie (le prêtre a béni l'eau ; une union bénie des dieux)." },
  { n:"R73", th:"verbe", t:"contredire, dédire, interdire, médire, prédire",
    e:"Contrairement à dire (vous dites), ces verbes font -disez : vous contredisez, vous interdisez, vous prédisez." },
  { n:"R74", th:"verbe", t:"contrefaire, défaire, refaire, satisfaire, surfaire",
    e:"Ils se conjuguent comme faire : vous défaites, vous satisfaites (et non « satisfaisez »), ils défont, qu'il satisfasse ; au futur : je satisferai, nous referons (et non « satisfairai », « refairons »)." },
  { n:"R72", th:"verbe", t:"convaincre/vaincre, convenir/venir : convainc ou convint ?",
    e:"Présent : il convainc, il vainc (avec c). Passé simple : il convainquit, il vainquit ; il convint, il vint (venir). Ne confondez pas « il convainc » (présent) et « il convint » (passé)." },
  { n:"R42", th:"verbe", t:"convenir : le choix de l'auxiliaire",
    e:"Convenir de (décider) se conjugue avec être dans la langue soignée : nous sommes convenus d'un rendez-vous. Convenir à (plaire) prend avoir : cette date m'a convenu." },
  { n:"R91-5", th:"verbe", t:"décrépi et décrépit",
    e:"Décrépi = dont le crépi s'en va (un mur décrépi). Décrépit = usé par l'âge (un vieillard décrépit, une maison décrépite)." },
  { n:"R75", th:"verbe", t:"se départir",
    e:"Se départir de = renoncer à, se conjugue comme partir : il ne se départ jamais de son calme (et non « il ne se départit » au présent)." },
  { n:"R62", th:"verbe", t:"faire : l'accent circonflexe",
    e:"Pas d'accent à « il fait » ni à « vous faites ». Le circonflexe ne sert qu'au passé simple pluriel (nous fîmes, vous fîtes) et au subjonctif imparfait (qu'il fît) ; il fit, au passé simple, n'en a pas." },
  { n:"R64", th:"verbe", t:"fut-ce et fût-ce",
    e:"« fût-ce » (subjonctif, avec accent) = même si c'était : fût-ce au prix de sa vie. « fut-ce » (passé simple) dans une interrogation : fut-ce une erreur ?" },
  { n:"R76", th:"verbe", t:"ressortir (à)",
    e:"Ressortir (sortir de nouveau) se conjugue comme sortir : il ressort. Ressortir à (= relever de) se conjugue comme finir : cela ressortit à la justice, ces affaires ressortissent au tribunal." },
  { n:"R91-6", th:"verbe", t:"subi et subit",
    e:"Subi = participe passé de subir (un préjudice subi). Subit = soudain (un changement subit, une pluie subite)." },
  { n:"R56", th:"verbe", t:"surseoir : futur et conditionnel",
    e:"Surseoir (à) = différer. Présent sans e : je sursois, il sursoit, nous sursoyons. Futur et conditionnel avec e : je surseoirai, nous surseoirions (sursoirai en orthographe de 1990), jamais « sursiérai » ni « sursoyerai ». Participe : sursis." },
  { n:"R77", th:"verbe", t:"vêtir, dévêtir, revêtir",
    e:"Se conjuguent sur vêtir (et non comme finir) : il vêt, ils revêtent, je me vêts. Participe : vêtu, revêtu." },
  { n:"R85", th:"verbe", t:"voir : indicatif ou subjonctif (voie/voit)",
    e:"Indicatif : il voit, tu vois, nous voyons. Subjonctif : qu'il voie, que tu voies, que nous voyions, que vous voyiez (pour que tu voies le résultat). Ne pas écrire « pour que tu vois » ni « que nous voyons »." },
  { n:"R67", th:"verbe", t:"les verbes en -indre",
    e:"Craindre, peindre, joindre : au présent, ils perdent le d : je crains, il peint, il joint (pas de d), nous craignons, ils peignent." },
  { n:"R68", th:"verbe", t:"les verbes en -oudre et -soudre",
    e:"Coudre, moudre gardent le d : il coud, il moud. Résoudre, dissoudre le perdent : il résout, il dissout (participes : résolu, dissous/dissoute — ou dissout/dissoute en nouvelle orthographe)." },
  { n:"R63", th:"verbe", t:"passé simple ou subjonctif imparfait : il eut / il eût",
    e:"« il eut, il fut, il alla » (passé simple, sans accent) racontent. « qu'il eût, qu'il fût, qu'il allât » (subjonctif imparfait, avec accent) après un verbe au passé : on craignait qu'il ne fût trop tard." },
  { n:"R65", th:"verbe", t:"passé antérieur ou conditionnel passé 2e forme",
    e:"« il eut fini » (passé antérieur, après quand/dès que). « il eût fini » (avec accent : conditionnel passé 2e forme, = il aurait fini) : il eût aimé venir." },
  { n:"R82", th:"verbe", t:"afin que, avant que, bien que, pour que… + subjonctif",
    e:"Ces conjonctions imposent le subjonctif : bien qu'il soit tard, avant qu'il (ne) parte, pour que tu comprennes, quoiqu'il en ait envie." },
  { n:"R91-3", th:"verbe", t:"cru et crû",
    e:"Participe de croire : cru (j'ai cru). Participe de croître : crû avec accent (les prix ont crû) — l'accent évite la confusion. Féminin/pluriel sans accent : crue, crus." },
  { n:"R93-2", th:"verbe", t:"le participe avec être quand le sujet est nous",
    e:"Avec le « nous » de modestie ou de majesté désignant une seule personne, le participe et l'adjectif restent au singulier et prennent le genre de cette personne : nous sommes convaincu (un auteur), convaincue (une femme). Sinon, accord au pluriel : nous sommes partis." },
  { n:"R95-3", th:"verbe", t:"donné, eu, laissé + à + infinitif",
    e:"Accord facultatif, souvent omis : les leçons qu'on m'a donné à apprendre (ou données). La tolérance joue dans les deux sens ; l'invariabilité est toujours acceptée." },
  { n:"R96", th:"verbe", t:"le participe passé précédé du pronom en",
    e:"Avec « en » COD, le participe reste invariable : des cerises, j'en ai mangé ; des difficultés, il en a rencontré." },
  { n:"R97", th:"verbe", t:"le participe passé des verbes impersonnels",
    e:"Toujours invariable : les chaleurs qu'il a fait, les inondations qu'il y a eu, la patience qu'il a fallu." },
  { n:"R98", th:"verbe", t:"le participe passé précédé de l' (COD neutre)",
    e:"Quand l' représente une proposition (= cela), pas d'accord : la journée fut plus belle qu'on ne l'avait espéré (on avait espéré cela)." },
  { n:"R99", th:"verbe", t:"le participe passé avec « le peu de »",
    e:"Si « le peu de » = l'insuffisance, participe invariable : le peu d'attention qu'il a montré. Si le complément domine, accord : le peu de forces qu'il a retrouvées." },
  { n:"R100", th:"verbe", t:"attendu, y compris, excepté, étant donné, vu…",
    e:"Placés devant le nom, attendu, excepté, vu, y compris, non compris jouent le rôle de prépositions et restent invariables : excepté les enfants, vu les circonstances. Placés après, ils s'accordent : les enfants exceptés, taxes comprises. Étant donné peut s'accorder ou non." },
  { n:"R102", th:"verbe", t:"couru, coûté, valu, vécu, pesé…",
    e:"Invariables avec un complément de mesure (combien ?) : les trois heures que le film a duré, les vingt euros que cela a coûté. Accord au sens figuré transitif : les efforts que ce projet m'a coûtés." },
  { n:"R103", th:"verbe", t:"dit, dû, cru, pu, su, voulu, permis, prévu…",
    e:"Invariables quand le vrai COD est un infinitif ou une proposition sous-entendue : il a fait tous les efforts qu'il a pu (faire), les sommes qu'il aurait dû (payer)." },
  { n:"R104-1", th:"verbe", t:"participe passé des pronominaux réfléchis et réciproques",
    e:"Accord avec le pronom s'il est COD : elle s'est blessée, ils se sont vus. Pas d'accord s'il est COI : ils se sont parlé, elles se sont succédé, elle s'est dit que…, elle s'est lavé les mains ; mais accord avec un COD placé avant : les mains qu'elle s'est lavées." },
  { n:"R104-2", th:"verbe", t:"pronominaux dont le pronom n'est pas analysable",
    e:"Verbes essentiellement pronominaux (s'évanouir, s'enfuir, se souvenir…) : accord avec le sujet : elle s'est évanouie, ils se sont enfuis. Exception : s'arroger s'accorde avec le COD placé avant : les droits qu'elle s'est arrogés, mais elle s'est arrogé des droits." },
  { n:"R104-3", th:"verbe", t:"pronominaux de sens passif",
    e:"Accord avec le sujet : ces livres se sont bien vendus, la ville s'est construite en dix ans." },
  { n:"R104-5", th:"verbe", t:"pronominal suivi d'un infinitif",
    e:"Accord si le sujet fait l'action de l'infinitif : elle s'est sentie tomber. Invariable sinon : elle s'est laissé convaincre (on la convainc), ils se sont vu refuser l'entrée. Depuis 1990, « laissé » + infinitif peut toujours rester invariable." },
  { n:"R104-6", th:"verbe", t:"se faire + infinitif",
    e:"« fait » suivi d'un infinitif reste invariable : elle s'est fait opérer, ils se sont fait avoir." },
  { n:"R104-7", th:"verbe", t:"se rendre compte, se faire l'écho, se faire fort de",
    e:"Participe invariable dans ces tours : elle s'est rendu compte de son erreur, ils se sont fait l'écho de la rumeur, elle s'est fait fort de réussir." },
  { n:"R86", th:"verbe", t:"participe présent, adjectif verbal, nom : -quant/-cant, -guant/-gant",
    e:"Participe (action, invariable) : en communiquant, en naviguant, un discours provoquant la colère. Adjectif/nom : communicant, navigant, provocant, fatigant, convaincant, intrigant, suffocant." },
  { n:"R105", th:"verbe", t:"l'accord du verbe avec un collectif (foule, groupe…)",
    e:"Après un, une (une foule de clients), accord selon le sens : attendait (l'ensemble) ou attendaient (les individus). Après le, la, ce, mon (la foule des badauds, ce groupe d'élèves), le singulier s'impose en principe." },
  { n:"R106", th:"verbe", t:"l'accord avec force, nombre de, quantité de",
    e:"Sans déterminant, nombre de, bon nombre de, quantité de et force appellent le pluriel : nombre de spectateurs sont partis, force détails ont été donnés. Précédé de « le », nombre impose le singulier : le nombre des inscrits a doublé." },
  { n:"R108", th:"verbe", t:"moins de deux, plus d'un",
    e:"Le verbe suit le nombre exprimé, non l'idée de quantité : moins de deux ans se sont écoulés (pluriel), plus d'un invité s'est trompé (singulier)." },
  { n:"R110", th:"verbe", t:"sujets désignant une seule réalité",
    e:"Quand deux sujets désignent la même chose ou personne, le verbe reste au singulier : cet ami et confident sait tout." },
  { n:"R111", th:"verbe", t:"sujets synonymes ou en gradation",
    e:"Avec des sujets quasi synonymes ou en gradation, accord avec le dernier : une gêne, un malaise, une angoisse l'envahit." },
  { n:"R112", th:"verbe", t:"sujets introduits par aucun, nul, pas un",
    e:"Répétés, ces sujets laissent le verbe au singulier : aucun bruit, aucun cri ne se fit entendre." },
  { n:"R113", th:"verbe", t:"sujets introduits par chaque et tout",
    e:"Chaque élève, chaque professeur reçoit… ; tout homme, toute femme a droit au respect : répétés devant chaque sujet, chaque et tout laissent le verbe au singulier." },
  { n:"R114", th:"verbe", t:"sujets liés par ainsi que, avec, comme…",
    e:"Si le second sujet est entre virgules (comparaison), accord avec le premier : le capitaine, ainsi que son second, fut décoré. Sans virgules (addition), pluriel possible : le frère comme la sœur sont blonds." },
  { n:"R115", th:"verbe", t:"sujets liés par ni ou par ou",
    e:"Avec ni… ni ou avec ou, pluriel si les sujets peuvent agir ensemble : ni Pierre ni Paul ne sont venus ; singulier si un seul peut agir : Pierre ou Paul sera élu. Personnes différentes : pluriel, la 1re l'emporte sur la 2e, la 2e sur la 3e (ni toi ni moi ne savons)." },
  { n:"R116", th:"verbe", t:"sujets repris par un terme englobant",
    e:"Quand un mot (tout, rien, chacun…) reprend l'énumération, il commande l'accord : livres, cahiers, stylos, tout avait disparu." },
  { n:"R117", th:"verbe", t:"trop + de + nom",
    e:"Accord avec le complément : trop de curieux s'attardent ; trop de sel gâte le plat." },

  /* ---------- Accords noms, adjectifs, tout ---------- */
  { n:"R118", th:"accord", t:"le pluriel des noms (s, x, z)",
    e:"Les noms en -s, -x, -z sont invariables au pluriel : des tas, des noix, des nez. Sept noms en -ou prennent un x : bijoux, cailloux, choux, genoux, hiboux, joujoux, poux. Les noms en -au, -eau, -eu prennent un x (tuyaux, feux), sauf notamment landaus, sarraus, pneus, bleus." },
  { n:"R149", th:"accord", t:"le pluriel des noms de couleur",
    e:"Employé comme nom, le mot de couleur s'accorde : des bleus profonds, les rouges de ce peintre. Placé après un nom, il suit la règle des adjectifs de couleur : des robes orange, des yeux marron." },
  { n:"R120", th:"accord", t:"le pluriel des noms de personnes",
    e:"Les noms de famille restent invariables : les Durand, les Martin. Seules quelques dynasties ou familles illustres prennent la marque du pluriel : les Bourbons, les Stuarts, les Tudors." },
  { n:"R89", th:"accord", t:"le pluriel d'ayant droit et ayant cause",
    e:"Des ayants droit, des ayants cause : « ayant » prend le s (emploi nominal), « droit » et « cause » restent au singulier." },
  { n:"R164", th:"accord", t:"nouveau-né, mort-né, premier-né, dernier-né",
    e:"« nouveau » et « mort » restent invariables (valeur adverbiale) : des enfants nouveau-nés, des filles mort-nées. Mais premier-né, dernier-né s'accordent entièrement : les premières-nées." },
  { n:"R140", th:"accord", t:"le nom après des ordinaux coordonnés",
    e:"On peut écrire « le XVe et le XVIe siècle » (chacun son article, nom au singulier) ou « les XVe et XVIe siècles » (article pluriel, nom au pluriel)." },
  { n:"R122", th:"accord", t:"autre chose, peu de chose, quelque chose",
    e:"Dans « quelque chose », « autre chose », « peu de chose » (= presque rien), « chose » reste au singulier : quelque chose d'important, c'est peu de chose. Le pluriel ne s'emploie que si « choses » garde son sens plein : il me reste quelques choses à régler." },
  { n:"R160", th:"accord", t:"force, nombre de, quantité de (accord du nom)",
    e:"Le nom qui suit se met au pluriel s'il désigne des réalités que l'on peut compter : force compliments, nombre d'erreurs, quantité de fruits. Un nom non comptable reste au singulier : quantité de sable." },
  { n:"R124", th:"accord", t:"être légion, battre son plein",
    e:"« Ils sont légion » (invariable). « Les fêtes battent leur plein » : plein est ici un nom (le plein), on accorde seulement le possessif : elle bat son plein, elles battent leur plein." },
  { n:"R121", th:"accord", t:"sans + nom",
    e:"Après « sans », singulier ou pluriel selon le sens : un ciel sans nuage(s), un texte sans fautes (qu'aurait-il en positif ? des fautes → pluriel ; du courage → singulier : sans courage)." },
  { n:"R148", th:"accord", t:"adjectifs de couleur coordonnés par et",
    e:"« des drapeaux bleu, blanc, rouge » (chaque drapeau a les trois couleurs : invariable) ; « des drapeaux bleus et blancs » (certains bleus, d'autres blancs : accord)." },
  { n:"R156", th:"accord", t:"l'accord avec avoir l'air",
    e:"Sujet de personne : accord avec le sujet (elle a l'air sérieuse = elle semble sérieuse) ou avec « air » (elle a l'air sérieux = elle a une mine sérieuse). Sujet de chose : accord avec le sujet seulement : cette tarte a l'air délicieuse." },
  { n:"R158", th:"accord", t:"l'adjectif après des plus",
    e:"Après « des plus », l'adjectif se met au pluriel : une situation des plus délicates (= parmi les plus délicates). Avec un pronom neutre ou un infinitif : singulier (cela est des plus normal)." },
  { n:"R162", th:"accord", t:"la plus / le plus + adjectif féminin",
    e:"Comparaison avec d'autres : article accordé (elle est la plus heureuse des femmes). Même être comparé à lui-même selon le moment ou les circonstances : le invariable (c'est le matin qu'elle est le plus heureuse ; c'est ici que la rivière est le plus profonde)." },
  { n:"R127", th:"accord", t:"l'accord de l'adjectif quand le sujet est nous",
    e:"Avec le nous de modestie/majesté (une personne), l'adjectif reste au singulier : nous sommes persuadé(e). Avec un vrai pluriel : nous sommes persuadés." },
  { n:"R131", th:"accord", t:"le pluriel d'avant et arrière",
    e:"Employés comme adjectifs, avant et arrière sont invariables : des feux arrière, les roues avant. En composition, seul l'autre élément varie : des arrière-boutiques, des avant-postes. Employés comme noms, ils s'accordent : les avants du pack, assurer ses arrières." },
  { n:"R155", th:"accord", t:"aucun et d'aucuns (et en congé, en vacances)",
    e:"« aucun » s'emploie au singulier sauf devant un nom toujours pluriel : aucuns frais. « d'aucuns » = certains : d'aucuns prétendent que… On est en congé (singulier) mais en vacances (pluriel)." },
  { n:"R129", th:"accord", t:"le pluriel de banal",
    e:"Sens courant : banals (des propos banals). Sens féodal (fours, moulins) : banaux." },
  { n:"R132", th:"accord", t:"le féminin de bénin, enclin, malin",
    e:"Bénin → bénigne ; malin → maligne ; enclin → encline. Une tumeur bénigne, une joie maligne." },
  { n:"R159", th:"accord", t:"l'adjectif feu (défunt)",
    e:"Invariable devant l'article ou le possessif : feu la reine. Accordé entre le déterminant et le nom : la feue reine, mes feus grands-parents." },
  { n:"R165", th:"accord", t:"l'accord de nu",
    e:"Placé devant le nom et joint à lui par un trait d'union, nu est invariable : nu-tête, nu-pieds. Placé après le nom, il s'accorde : tête nue, pieds nus. Exception juridique : la nue-propriété, les nus-propriétaires." },
  { n:"R166", th:"accord", t:"l'accord de possible",
    e:"Invariable après « le plus / le moins » + nom : le plus de points possible (sous-entendu « qu'il est possible »). Accordé sinon : tous les scénarios possibles." },
  { n:"R169", th:"accord", t:"l'accord de tel et tel que",
    e:"« tel » s'accorde avec ce qui suit : tels des oiseaux. « tel que » s'accorde avec ce qui précède : des sports tels que la natation. « tel quel » s'accorde : je rends la maison telle quelle." },
  { n:"R144", th:"accord", t:"un dans un nombre",
    e:"« un » s'accorde en genre : vingt et une pages. « Page un » (numéro) peut rester invariable : la page un du journal." },
  { n:"R161", th:"accord", t:"l'accord avec gens",
    e:"Adjectif juste avant gens : féminin (de vieilles gens) ; placé après ou attribut : masculin (des gens sérieux, ces gens sont heureux). Tout ne prend le féminin que si l'adjectif qui le suit a une forme féminine distincte : toutes ces vieilles gens, mais tous ces braves gens." },
  { n:"R168", th:"accord", t:"Son Éminence, Sa Majesté…",
    e:"Les titres féminins commandent le féminin, sauf si le nom réel suit : Sa Majesté est attendue ; mais Sa Majesté le roi est attendu." },
  { n:"R130", th:"accord", t:"les adjectifs employés comme adverbes",
    e:"Employés adverbialement, ils sont invariables : ces fleurs sentent bon, elles coûtent cher, ils parlent fort, voir grand." },
  { n:"R134", th:"adv", t:"les adverbes en -ment",
    e:"Les adverbes en -ment se forment sur le féminin de l'adjectif : douce → doucement, folle → follement. Si le masculin finit par -ai, -é, -i, -u, on part du masculin : vraiment, aisément, poliment, absolument (sauf gaiement). Certains prennent -ément : précisément, énormément." },
  { n:"R135", th:"adv", t:"les adverbes en -ûment",
    e:"Certains adverbes tirés d'adjectifs en -u prennent un accent circonflexe, jamais de e : assidûment, continûment, crûment, dûment, goulûment, indûment ; mais éperdument, résolument, ingénument, absolument. (Rectifications de 1990 : assidument, dument… admis.)" },
  { n:"R151-2", th:"adv", t:"tout adverbe devant h",
    e:"Devant un adjectif féminin à h muet, tout reste invariable : elle est tout heureuse. Devant h aspiré, comme devant une consonne, il s'accorde : elle est toute honteuse, elles sont toutes hérissées. Au masculin, aucun accord : ils sont tout honteux." },
  { n:"R152", th:"accord", t:"tout autre et toute autre",
    e:"« toute autre » quand tout qualifie le nom (n'importe quelle autre : toute autre solution). « tout autre » quand tout modifie autre (= complètement différent : c'est une tout autre histoire)." },
  { n:"R153", th:"accord", t:"tout à vous, toute à vous",
    e:"« Tout à vous » est la formule de politesse d'usage (= entièrement dévoué) : un homme écrit toujours « tout à vous » ; une femme peut accorder et écrire « toute à vous ». Jamais « tous » pour une seule personne." },
  { n:"R154", th:"accord", t:"les expressions avec tout ou tous",
    e:"À tout prix, à tout hasard, en tout état de cause (singulier) ; en toutes lettres, de toutes pièces, à toutes jambes, toutes affaires cessantes (pluriel) ; à toute vitesse, en toute franchise (féminin singulier). Usage figé : à mémoriser." },

  /* ---------- Savoir orthographier (lexique) ---------- */
  { n:"R191-3", th:"orth", t:"les suffixes -iatre et -âtre",
    e:"-iatre (médecin, sans accent) : psychiatre, pédiatre, gériatre, d'où pédiatrie. -âtre (sens approximatif ou péjoratif, avec accent circonflexe) : blanchâtre, verdâtre, douceâtre, marâtre, bellâtre." },
  { n:"R172-2", th:"orth", t:"les mots en dis-/dys- et hippo-/hypo-",
    e:"dys- = trouble (dyslexie, dysfonctionnement) ; dis- = séparation (disparaître, dissiper). hippo- = cheval (hippodrome) ; hypo- = sous (hypothèse, hypoglycémie)." },
  { n:"R37-2", th:"orth", t:"les noms en -er issus de verbes",
    e:"Les infinitifs devenus noms gardent -er : le coucher du soleil, le lever, le toucher, un parler régional, le dîner, le goûter. Ne pas confondre avec les noms en -é : le passé, le marché, le fossé." },
  { n:"R174", th:"orth", t:"les noms et adjectifs en -ote/-otte",
    e:"Un seul t : note, pilote, anecdote, et la plupart des féminins en -ote (idiote, dévote, bigote, falote, manchote). Deux t : botte, carotte, culotte, menotte, biscotte, et quelques féminins : sotte, pâlotte, vieillotte, boulotte." },
  { n:"R173", th:"orth", t:"les verbes en res-/ress-",
    e:"Pour garder le son [s] entre re- et une voyelle, on double le s : ressembler, ressentir, ressortir, ressaisir, ressource. Quelques mots gardent un seul s : resituer, resalir, resocialiser. Resurgir s'écrit aussi ressurgir." },
  { n:"R176", th:"orth", t:"les noms féminins en -u",
    e:"Les noms féminins en -u prennent un e : la rue, la vue, la tenue… sauf bru, glu, tribu, vertu." },
  { n:"R177", th:"orth", t:"les noms féminins en -ussion",
    e:"S'écrivent -ussion : discussion, percussion, répercussion, concussion (avec ss, pas -ution)." },
  { n:"R217", th:"orth", t:"etc.",
    e:"« etc. » s'abrège avec un seul point et se place après une virgule. Il n'est jamais suivi de points de suspension ni précédé de « et » : des fruits, des légumes, etc. En fin de phrase, son point d'abréviation sert aussi de point final." },
  { n:"R191-2", th:"orth", t:"pèlerin, pèlerinage, pèlerine",
    e:"Accent grave sur le premier e, ni accent aigu ni accent circonflexe, et un seul l : un pèlerin, une pèlerine, partir en pèlerinage." },
  { n:"R31-2", th:"orth", t:"quelque : l'adverbe, quelque… que",
    e:"Adverbe (= environ, ou = si devant un adjectif) : invariable : quelque deux cents personnes ; quelque puissants qu'ils soient. Déterminant devant un nom, même dans quelque… que : accord : quelques amis, quelque temps, quelques efforts que tu fasses." },
  { n:"R186", th:"orth", t:"aborigène, fruste, pécuniaire, pénitentiaire, sectaire",
    e:"Orthographes sans variante : aborigène (pas « arborigène »), fruste (pas « frustre »), pécuniaire au masculin comme au féminin (pas « pécunier »), pénitentiaire avec t, comme pénitent (« pénitencier » est un nom), sectaire." },
  { n:"R184", th:"orth", t:"faire bonne chère",
    e:"« faire bonne chère » = bien manger (chère = la nourriture, à l'origine le visage), et non « bonne chair »." },
  { n:"R185", th:"orth", t:"là où le bât blesse",
    e:"« C'est là que le bât blesse » (ou « voilà où le bât blesse ») : le bât, avec accent circonflexe, est la selle des bêtes de somme ; ne pas écrire « bas » ni « bat ». Ex. : Le prix, voilà où le bât blesse." },

  /* ---------- Apostrophe, trait d'union, majuscule, soudure ---------- */
  { n:"R194", th:"signes", t:"l'élision de jusque",
    e:"Jusque s'élide devant voyelle : jusqu'à, jusqu'ici, jusqu'en. « jusques » ne survit que dans quelques tours figés (jusques et y compris)." },
  { n:"R198", th:"signes", t:"le trait d'union avec chef",
    e:"Pas de trait d'union dans les locutions avec « de » ou « en » : chef de service, chef d'orchestre, rédacteur en chef. Trait d'union quand chef suit directement un nom : adjudant-chef, gardien-chef. Exceptions figées : chef-d'œuvre, chef-lieu." },
  { n:"R199", th:"signes", t:"le trait d'union après à demi",
    e:"Devant un adjectif, pas de trait d'union : à demi mort, une bouteille à demi vide. Devant un nom : trait d'union : à demi-mot, à demi-tarif." },
  { n:"R200", th:"signes", t:"le trait d'union après quasi",
    e:"Devant un nom : trait d'union (la quasi-totalité, un quasi-monopole). Devant un adjectif ou un adverbe : pas de trait d'union (quasi impossible, quasi toujours)." },
  { n:"R201", th:"signes", t:"le trait d'union après un impératif",
    e:"Trait d'union entre l'impératif et le ou les pronoms qui le suivent : donne-le-moi, allez-y, prends-en ; apostrophe après élision : va-t'en, donne-m'en. Pas de trait d'union si le pronom dépend de l'infinitif suivant : viens me voir, va le chercher." },
  { n:"R202", th:"signes", t:"le trait d'union dans les fractions",
    e:"Pas de trait d'union entre le numérateur et le dénominateur : un tiers, les deux tiers, les trois quarts, cinq centièmes. Le numérateur suit la règle des nombres : vingt-trois centièmes. Mais un trois-quarts (manteau, joueur de rugby) est un nom composé." },
  { n:"R203", th:"signes", t:"le trait d'union dans les noms de rues",
    e:"Les éléments du nom propre sont reliés : la rue Victor-Hugo, la place du Général-de-Gaulle, le lycée Louise-Michel." },
  { n:"R204", th:"signes", t:"le trait d'union devant -ci et -là",
    e:"Trait d'union entre le démonstratif et -ci ou -là : celui-ci, ces jours-là, ce livre-ci. Aussi dans là-bas, là-haut, là-dessus, jusque-là. Mais « là » seul, adverbe de lieu, reste libre : il est là, reste là." },
  { n:"R206", th:"signes", t:"le trait d'union après contre",
    e:"Beaucoup de composés de contre sont soudés : contrebasse, contrepoids, contrefaçon, contredire. D'autres prennent le trait d'union : contre-exemple, contre-indication, contre-jour, contre-plongée (les rectifications de 1990 admettent leur soudure). Jamais d'espace." },
  { n:"R208", th:"signes", t:"s'ensuivre",
    e:"Le verbe s'ensuivre s'écrit soudé : il s'ensuit que…, les débats qui s'ensuivirent, ce qui va s'ensuivre. On n'écrit pas « il s'en suit ». Aux temps composés, « il s'en est suivi » est admis à côté de « il s'est ensuivi »." },
  { n:"R209", th:"signes", t:"entre dans la composition d'un mot",
    e:"Beaucoup de composés d'entre sont soudés : entracte, entraide, s'entraider, entrouvrir, entrevoir, entrecôte (l'ancienne apostrophe a disparu). Quelques-uns gardent le trait d'union dans l'orthographe traditionnelle : entre-temps, entre-deux." },
  { n:"R207", th:"signes", t:"ledit, ladite, audit…",
    e:"Soudés : ledit contrat, ladite maison, lesdits documents, audit endroit, dudit terrain, desdites clauses (langue juridique). Mais à ladite, de ladite : la préposition reste détachée devant « ladite »." },
  { n:"R213", th:"signes", t:"la majuscule à état, église et lune",
    e:"Majuscule pour l'institution ou l'astre : l'État français, l'Église catholique, la Lune (astronomie). Minuscule pour l'état d'esprit, le bâtiment église, un clair de lune." },
  { n:"R214", th:"signes", t:"habitants, adjectifs et langues",
    e:"Majuscule au nom d'habitant (les Français, une Italienne), minuscule à l'adjectif (la cuisine française) et au nom de langue (parler français)." },
  { n:"R215", th:"signes", t:"nord, sud, est, ouest",
    e:"Majuscule quand le point cardinal désigne une région ou un ensemble géopolitique (vivre dans le Sud, le pôle Nord, l'Amérique du Sud, l'Est et l'Ouest) ; minuscule pour la direction ou devant un complément (vers le sud, au sud de Lyon, le nord de la France)." },

  /* ---------- Employer correctement ---------- */
  { n:"R224", th:"conf", t:"à et en (à Avignon, à bicyclette)",
    e:"Devant un nom de ville : « à » (à Avignon ; « en Avignon » est un tour ancien et régional). Monture ou engin qu'on enfourche : « à » (à vélo, à moto, à cheval) ; véhicule dans lequel on prend place : « en » (en voiture, en train, en avion)." },
  { n:"R225", th:"conf", t:"à et ou (de deux à quatre, deux ou trois)",
    e:"« à » entre deux nombres suppose une continuité : de deux à quatre heures. Sans continuité possible : « ou » (deux ou trois personnes — pas deux personnes et demie !)." },
  { n:"R226", th:"conf", t:"aussi… que et autant… que",
    e:"« aussi » + adjectif/adverbe : il est aussi grand que toi. « autant » + verbe ou nom : il travaille autant que toi, autant de courage." },
  { n:"R240", th:"conf", t:"causer",
    e:"On cause DE quelque chose AVEC quelqu'un. « causer à quelqu'un » est familier/critiqué : préférez « parler à quelqu'un »." },
  { n:"R227", th:"conf", t:"dans et sur (dans le journal, sur une liste)",
    e:"On lit une nouvelle dans le journal (et non « sur le journal ») ; on est inscrit sur une liste, mais on s'assoit dans un fauteuil et sur une chaise." },
  { n:"R228", th:"conf", t:"de (c'est ma faute, merci, remercier)",
    e:"On écrit « c'est ma faute » plutôt que « c'est de ma faute ». Merci, remercier : « de » ou « pour » devant un nom (merci de/pour votre aide), mais seulement « de » devant un infinitif (merci de m'avoir aidé). On intéresse quelqu'un à quelque chose." },
  { n:"R229", th:"conf", t:"de façon que et de manière que",
    e:"Pour exprimer le but, la langue soignée emploie « de façon que », « de manière que » + subjonctif : parle fort de façon qu'on t'entende. « De façon à ce que » est critiqué comme lourd. Pour la conséquence, indicatif : il a agi de telle façon que tout a réussi." },
  { n:"R230", th:"conf", t:"de par",
    e:"« de par » est correct dans « de par le monde » et « de par la loi » (= de la part de). Pour la cause, préférez « du fait de, en raison de » à « de par sa taille »." },
  { n:"R232", th:"conf", t:"dont et d'où",
    e:"« D'où » marque le lieu réel d'où l'on vient ou sort : la ville d'où je viens, la pièce d'où il sort. « Dont » marque l'origine, la descendance : la famille dont il descend, le milieu dont il est sorti. « D'où » marque aussi la conséquence : d'où ma surprise." },
  { n:"R231", th:"conf", t:"ès",
    e:"« ès » = en les : il ne s'emploie que devant un pluriel : docteur ès lettres, licencié ès sciences." },
  { n:"R249", th:"conf", t:"et autres",
    e:"« et autres » doit être suivi d'un terme englobant : des pommes, des poires et autres fruits (et non « et autres » tout seul en fin d'énumération, ni suivi d'un terme non englobant)." },
  { n:"R221-2", th:"conf", t:"jamais sans particule négative, ne explétif",
    e:"« Jamais » sans « ne » signifie « un jour » : si jamais tu passes ; le plus beau film que j'aie jamais vu (sans « ne »). Le ne explétif (je crains qu'il ne vienne) n'est pas une négation : il peut s'omettre, mais n'y ajoutez pas « pas » si l'on craint sa venue." },
  { n:"R233", th:"conf", t:"lez (lès)",
    e:"« lez/lès » = près de, dans les noms de lieux : Plessis-lez-Tours, Villeneuve-lès-Avignon." },
  { n:"R234", th:"conf", t:"plutôt que (de)",
    e:"Devant un infinitif : plutôt que de partir (le « de » est usuel, son omission est admise). Devant un nom, pas de « de » ajouté (plutôt que la fuite), sauf si la construction l'exige (besoin de calme plutôt que de bruit). À distinguer de « plus tôt » : plus tôt que prévu." },

  /* ---------- Sens des mots et expressions ---------- */
  { n:"R251", th:"conf", t:"acceptation et acception",
    e:"Acceptation = fait d'accepter. Acception = sens d'un mot : dans toutes les acceptions du terme." },
  { n:"R294", th:"conf", t:"accro et accroc",
    e:"Accro (familier) = dépendant, passionné : accro au café. Un accroc (c final) = une déchirure, un incident : un accroc dans le contrat." },
  { n:"R252", th:"conf", t:"achalandé et approvisionné",
    e:"Achalandé = qui a des chalands (des clients). Un magasin bien approvisionné (ou fourni) a beaucoup de marchandises ; « bien achalandé » en ce sens est critiqué." },
  { n:"R295", th:"conf", t:"acquis et acquit",
    e:"Acquis = participe d'acquérir (obtenu) : des droits acquis, être acquis à une cause, les acquis sociaux. Acquit = nom tiré d'acquitter : par acquit de conscience, pour acquit. Attention : « il acquit » est aussi le passé simple d'acquérir." },
  { n:"R253", th:"conf", t:"agonir et agoniser (sens)",
    e:"Agonir quelqu'un d'injures = l'en accabler ; il se conjugue comme finir : il l'a agoni, ils l'agonissent. Agoniser = être à l'agonie : le blessé agonise. « Il m'a agonisé d'injures » est incorrect." },
  { n:"R254", th:"conf", t:"alcoolique et alcoolisé",
    e:"Alcoolique = dépendant de l'alcool (un malade alcoolique) ou relatif à l'alcool (une intoxication alcoolique). Alcoolisé = additionné d'alcool : un sorbet alcoolisé. Pour une boisson, les deux adjectifs sont admis." },
  { n:"R237", th:"conf", t:"alternative",
    e:"Une alternative = un choix entre deux possibilités (être placé devant une alternative). Le mot ne désigne pas l'une des possibilités : dites « deux possibilités », « une autre solution », et non « deux alternatives », « pas d'autre alternative »." },
  { n:"R255", th:"conf", t:"amener et apporter",
    e:"On amène une personne (ou un être qui se déplace), on apporte un objet : amène ta sœur, apporte le dessert. De même emmener/emporter." },
  { n:"R296", th:"conf", t:"appas et appâts",
    e:"Les appas (sans t) = les charmes. Un appât (avec t) = ce qui attire (pêche, piège) : mordre à l'appât." },
  { n:"R256", th:"conf", t:"arcade et arcane",
    e:"Une arcade = ouverture en arc (les arcades d'une place, l'arcade sourcilière). Les arcanes (masculin) = les secrets : les arcanes du pouvoir." },
  { n:"R284", th:"conf", t:"au regard de et en regard de",
    e:"Au regard de = du point de vue de, par rapport à (au regard de la loi). En regard (de) = en face (de), vis-à-vis (texte et traduction en regard) ; par extension, en comparaison de (un gain faible en regard des efforts)." },
  { n:"R238", th:"conf", t:"avatar",
    e:"Un avatar = une métamorphose, une incarnation (les avatars de Vishnou ; les avatars d'une doctrine). L'emploi au sens de « mésaventure, ennui » est critiqué : on parle alors de déboires, de contretemps, d'incidents." },
  { n:"R285", th:"conf", t:"avoir des chances de et risquer de",
    e:"« chance » pour l'heureux (il a des chances de gagner), « risque » pour le fâcheux (il risque de perdre). « Il risque de gagner » est illogique." },
  { n:"R297", th:"conf", t:"bailler, bâiller et bayer",
    e:"Bâiller (accent) = ouvrir largement la bouche (fatigue, ennui) ou être entrouvert (la porte bâille). Bayer aux corneilles = rêvasser, regarder en l'air. Bailler (sans accent, vieilli) = donner : vous me la baillez belle." },
  { n:"R298", th:"conf", t:"balade et ballade",
    e:"Une balade (un l) = une promenade ; de même se balader, un baladeur. Une ballade (deux l) = un poème à forme fixe ou une pièce musicale : les ballades de Villon, une ballade de Chopin." },
  { n:"R299", th:"conf", t:"but et butte",
    e:"Un but = objectif. Une butte = petite colline ; être en butte à = être exposé à (il est en butte aux critiques, et non « en but »)." },
  { n:"R300", th:"conf", t:"cahot et chaos",
    e:"Un cahot = une secousse (route cahoteuse). Le chaos = le désordre (une situation chaotique). Les deux se prononcent de la même façon, d'où la confusion." },
  { n:"R301", th:"conf", t:"céans et séant",
    e:"Céans = ici (le maître de céans). Le séant = le derrière (se dresser sur son séant) ; séant (adjectif) = convenable." },
  { n:"R258", th:"conf", t:"ceci et cela",
    e:"Ceci annonce ce qui suit ; cela reprend ce qui précède : retenez ceci : … ; il a plu, cela m'a surpris. « ceci dit » est critiqué au profit de « cela dit »." },
  { n:"R303", th:"conf", t:"cession et session",
    e:"Cession (céder) = transfert : la cession d'un fonds. Session (siéger) = période : la session d'examens." },
  { n:"R259", th:"conf", t:"clore et clôturer",
    e:"Clore = fermer, mettre fin à : on clôt une séance, un débat. Clôturer = entourer d'une clôture ; au sens de « terminer », il est admis mais moins soutenu. Seule la forme il clôt prend l'accent circonflexe : clore, clos, close, closent, clora n'en ont pas." },
  { n:"R260", th:"conf", t:"collision et collusion",
    e:"Collision = choc (une collision entre deux voitures). Collusion = entente secrète (collusion entre juges et politiques)." },
  { n:"R241", th:"conf", t:"commémorer",
    e:"On commémore un événement (commémorer l'armistice), on célèbre ou marque un anniversaire. « Commémorer un anniversaire » est un pléonasme critiqué." },
  { n:"R261", th:"conf", t:"conjecture et conjoncture",
    e:"Conjecture = supposition (se perdre en conjectures). Conjoncture = situation d'ensemble (la conjoncture économique)." },
  { n:"R242", th:"conf", t:"conséquent",
    e:"Conséquent = qui raisonne avec logique (être conséquent avec soi-même). Pour « important », dites considérable : une somme considérable (« somme conséquente » est critiqué)." },
  { n:"R191-1", th:"conf", t:"cote et côte",
    e:"La cote (sans accent) = valeur, évaluation, niveau chiffré : la cote d'un tableau, une cote de popularité, la cote d'un fleuve. La côte = os, pente ou rivage : une côte de veau, gravir une côte, la Côte d'Azur. Le côté = le flanc." },
  { n:"R286", th:"conf", t:"coupe claire et coupe sombre",
    e:"En forêt, la coupe sombre est légère (le sous-bois reste ombragé), la coupe claire est sévère (elle fait entrer la lumière). Au figuré, « coupes claires » est le plus logique pour des réductions drastiques, mais « coupes sombres » y est admis par l'usage." },
  { n:"R304", th:"conf", t:"crac, crack, craque et krach",
    e:"Crac ! (bruit sec). Un crack = un champion. Une craque = un mensonge. Un krach = effondrement boursier (le krach de 1929)." },
  { n:"R287", th:"conf", t:"de concert et de conserve",
    e:"De concert = d'un commun accord, après concertation (agir de concert avec un partenaire). De conserve = ensemble, en suivant la même route (naviguer de conserve). Les deux sont invariables ; « en concert » dans ce sens est un anglicisme." },
  { n:"R288", th:"conf", t:"de suite et tout de suite",
    e:"Tout de suite = immédiatement : viens tout de suite. De suite = d'affilée : trois jours de suite. « J'arrive de suite » est familier/critiqué." },
  { n:"R262", th:"conf", t:"décade et décennie",
    e:"Une décade = dix jours ; une décennie = dix ans. L'emploi de décade pour dix ans (anglicisme) est critiqué." },
  { n:"R263", th:"conf", t:"dentition et denture",
    e:"La denture = l'ensemble des dents : une denture saine, la denture d'une roue dentée. La dentition = la formation et la sortie des dents : les troubles de la dentition. « Une belle dentition » est courant mais critiqué." },
  { n:"R264", th:"conf", t:"détente et gâchette",
    e:"On appuie sur la détente (pièce que presse le tireur) ; la gâchette est une pièce interne. « Appuyer sur la gâchette » est l'abus courant." },
  { n:"R305", th:"conf", t:"détoner et détonner",
    e:"Détoner (un n) = exploser : faire détoner une charge, un mélange détonant. Détonner (deux n) = sortir du ton, chanter faux ; au figuré, contraster : sa tenue détonnait dans l'assemblée." },
  { n:"R265", th:"conf", t:"deuxième et second",
    e:"Second et deuxième sont interchangeables : réserver second à une série de deux n'est qu'une préférence. Mais on dit de seconde main, seconde nature, en second, de second ordre, le Second Empire, et toujours deuxième dans les composés : vingt-deuxième." },
  { n:"R307", th:"conf", t:"s'égailler et s'égayer",
    e:"S'égailler = se disperser (la troupe s'égaille). S'égayer = se réjouir. Prononciations distinctes : [egaje] / [egɛje]." },
  { n:"R266", th:"conf", t:"empreint et emprunt",
    e:"Empreint de = marqué de (un ton empreint de gravité). Un emprunt = ce qu'on emprunte (rembourser un emprunt)." },
  { n:"R243", th:"conf", t:"éponyme",
    e:"Éponyme = qui donne son nom : Romulus, éponyme de Rome ; Phèdre, héroïne éponyme de la tragédie. Appliqué à l'œuvre elle-même (« l'album éponyme »), l'emploi est répandu mais critiqué : dites « le film du même nom ». Ne confondez pas avec homonyme (qui porte le même nom qu'un autre)." },
  { n:"R267", th:"conf", t:"excessivement et extrêmement",
    e:"Excessivement = trop, avec excès (excessivement salé = trop salé). Pour un simple degré élevé, dites extrêmement : extrêmement intéressant." },
  { n:"R308", th:"conf", t:"exprès et express",
    e:"Exprès/expresse = formel (défense expresse) ; « exprès » adverbe = volontairement (il l'a fait exprès) ; une lettre exprès. Express = rapide (train express, café express)." },
  { n:"R250", th:"conf", t:"faire long feu",
    e:"Faire long feu = échouer, manquer son but, comme une cartouche dont la charge brûle trop lentement (la tentative a fait long feu). « Ne pas faire long feu » = ne pas durer. Ne dites pas « faire long feu » pour « durer longtemps »." },
  { n:"R289", th:"conf", t:"faute d'attention et faute d'inattention",
    e:"« Faute d'inattention » (nom) = erreur due à l'inattention : une faute d'inattention. « Faute d'attention » (locution) = par manque d'attention : faute d'attention, il a échoué. « Faute d'inattention, il a échoué » signifierait « par manque d'inattention » : absurde." },
  { n:"R244", th:"conf", t:"finaliser",
    e:"Finaliser = donner un but (sens premier) ; l'emploi pour « mener à terme » (finaliser un dossier) est un anglicisme admis dans l'usage professionnel mais critiqué en langue soignée." },
  { n:"R309", th:"conf", t:"foi, foie et fois",
    e:"La foi = croyance (avoir la foi, ma foi). Le foie = l'organe. La fois = l'occurrence (une fois, il était une fois)." },
  { n:"R311", th:"conf", t:"gent et gente",
    e:"La gent (sans e) = le peuple, l'espèce : la gent féminine. « gente » est un adjectif archaïque (gente dame). N'écrivez pas « la gente féminine »." },
  { n:"R268", th:"conf", t:"gradation et graduation",
    e:"Gradation = progression par degrés (une gradation dans l'effort). Graduation = les divisions d'un instrument (la graduation d'un thermomètre)." },
  { n:"R312", th:"conf", t:"gril et grill",
    e:"Le gril (prononcé « gri » ou « gril ») = l'ustensile (cuire au gril, être sur le gril). Grill (anglicisme) = le restaurant (un grill-room)." },
  { n:"R269", th:"conf", t:"hiberner et hiverner",
    e:"Hiberner = passer l'hiver en léthargie (la marmotte hiberne). Hiverner = passer l'hiver à l'abri (les troupeaux hivernent dans la vallée)." },
  { n:"R290", th:"conf", t:"il faut mieux et il vaut mieux",
    e:"« il vaut mieux » = il est préférable : il vaut mieux partir tôt. « il faut mieux » = il faut quelque chose de meilleur : il faut mieux que ça pour me convaincre." },
  { n:"R270", th:"conf", t:"inclinaison et inclination",
    e:"Inclinaison = pente physique (l'inclinaison du toit). Inclination = penchant, goût (une inclination pour la musique) ; saluer d'une inclination de tête." },
  { n:"R245", th:"conf", t:"ingambe",
    e:"Ingambe = alerte, qui a de bonnes jambes (un vieillard encore ingambe) — et non « impotent » ! Le in- n'est pas négatif ici (italien in gamba)." },
  { n:"R246", th:"conf", t:"initier",
    e:"Initier = faire découvrir (initier quelqu'un à la peinture). L'emploi « initier un projet » (= lancer) est un anglicisme critiqué : préférez lancer, engager, entamer." },
  { n:"R271", th:"conf", t:"intense et intensif",
    e:"Intense = très fort, d'un haut degré (un froid intense, une émotion intense). Intensif = qui concentre des moyens ou des efforts pour obtenir davantage (un stage intensif, la culture intensive, les soins intensifs)." },
  { n:"R272", th:"conf", t:"jadis et naguère",
    e:"Jadis = il y a longtemps. Naguère = il n'y a guère (de temps), récemment — et non « autrefois »." },
  { n:"R313", th:"conf", t:"martyr et martyre",
    e:"Un martyr, une martyre = la personne qui souffre ou meurt pour une cause ; employé comme adjectif, le mot s'accorde : un enfant martyr, une ville martyre. Le martyre = le supplice lui-même : souffrir le martyre." },
  { n:"R291", th:"conf", t:"mettre à jour et mettre au jour",
    e:"Mettre à jour = actualiser (mettre à jour un fichier). Mettre au jour = déterrer, révéler (les fouilles ont mis au jour une mosaïque)." },
  { n:"R273", th:"conf", t:"mystifier et mythifier",
    e:"Mystifier = tromper, duper (mystifier un public crédule). Mythifier = transformer en mythe (mythifier une époque). De même, démystifier = détromper ou ôter le mystère (démystifier l'informatique) ; démythifier = ôter son caractère de mythe (démythifier un héros)." },
  { n:"R274", th:"conf", t:"occasion et opportunité",
    e:"Opportunité = caractère opportun (discuter de l'opportunité d'une réforme). Pour « occasion favorable », préférez occasion : saisir l'occasion (l'« opportunité à saisir » est un anglicisme critiqué)." },
  { n:"R275", th:"conf", t:"oppresser et opprimer",
    e:"Oppresser = gêner la respiration, angoisser (la chaleur m'oppresse). Opprimer = soumettre par la force (opprimer un peuple)." },
  { n:"R276", th:"conf", t:"poindre et pointer",
    e:"Poindre = commencer à paraître ; il se conjugue comme joindre : le jour point, l'aube poignait, le jour poindra. Pointer = diriger, cocher (pointer une arme, une liste). « Le jour pointe » est admis, « le jour point » est plus soutenu." },
  { n:"R316", th:"conf", t:"prémices et prémisse",
    e:"Les prémices (féminin pluriel) = les débuts, premiers fruits : les prémices du printemps. Une prémisse = proposition d'un raisonnement." },
  { n:"R277", th:"conf", t:"prolongation et prolongement",
    e:"Prolongation = durée ajoutée (les prolongations d'un match, la prolongation d'un contrat). Prolongement = extension dans l'espace (le prolongement d'une ligne de métro) ; dans le prolongement de." },
  { n:"R278", th:"conf", t:"publiciste et publicitaire",
    e:"Un publiciste = juriste de droit public ou journaliste (vieilli). Le professionnel de la publicité est un publicitaire." },
  { n:"R317", th:"conf", t:"raisonner et résonner",
    e:"Raisonner = faire usage de la raison (raisonner juste, raisonner quelqu'un). Résonner = produire un écho (la salle résonne)." },
  { n:"R279", th:"conf", t:"ranimer et réanimer",
    e:"Réanimer = rétablir les fonctions vitales, en médecine (réanimer un noyé, service de réanimation). Ranimer = redonner vigueur ou éclat (ranimer le feu, l'espoir, un souvenir) ; il signifie aussi « faire revenir à soi ». Au figuré, on emploie ranimer." },
  { n:"R247", th:"conf", t:"réaliser",
    e:"Réaliser = rendre réel (réaliser un rêve). Au sens de « prendre conscience » (je réalise soudain), c'est un anglicisme entré dans l'usage mais critiqué en langue soignée." },
  { n:"R280", th:"conf", t:"recouvrer, recouvrir et retrouver",
    e:"Recouvrer = rentrer en possession de, retrouver (recouvrer la vue, une créance) ; participe recouvré, futur recouvrera. Recouvrir = couvrir entièrement ou de nouveau ; participe recouvert, futur recouvrira. Il a recouvré la santé, mais recouvert le lit." },
  { n:"R318", th:"conf", t:"repaire et repère",
    e:"Un repaire = refuge d'animaux ou de brigands. Un repère = une marque (un point de repère, perdre ses repères)." },
  { n:"R292", th:"conf", t:"rien de moins que et rien moins que",
    e:"Rien de moins que = bel et bien (ce n'est rien de moins qu'un exploit = c'est vraiment un exploit). Rien moins que = nullement (il n'est rien moins que sûr = il n'est pas du tout sûr). Le contexte doit lever toute ambiguïté." },
  { n:"R319", th:"conf", t:"satire et satyre",
    e:"Une satire = écrit ou discours moqueur : faire la satire des mœurs, un journal satirique. Un satyre = créature mythologique mi-homme mi-bouc, ou homme lubrique ; d'où le drame satyrique des Grecs, joué par un chœur de satyres." },
  { n:"R320", th:"conf", t:"sceptique et septique",
    e:"Sceptique = qui doute (rester sceptique). Septique = qui infecte (une fosse septique, un choc septique)." },
  { n:"R281", th:"conf", t:"somptuaire et somptueux",
    e:"Somptueux = d'une magnificence coûteuse (un décor somptueux, une robe somptueuse). Somptuaire = relatif aux dépenses, notamment de luxe (lois somptuaires ; dépenses somptuaires = dépenses de luxe). Ne jamais employer somptuaire au sens de « magnifique »." },
  { n:"R293", th:"conf", t:"sous l'empire de et sous l'emprise de",
    e:"Empire = autorité, domination : sous l'empire de la colère ; avoir de l'empire sur soi (se maîtriser). Emprise = mainmise, ascendant (l'emprise d'un manipulateur, de l'alcool) et, au sens propre, terrain occupé : l'emprise au sol d'un bâtiment." },
  { n:"R282", th:"conf", t:"suggestion et sujétion",
    e:"Suggestion = idée proposée (une suggestion pertinente). Sujétion = dépendance, contrainte (la sujétion à un maître)." },
  { n:"R133", th:"conf", t:"volatil et volatile",
    e:"Volatil, volatile (adjectif) = qui s'évapore (un liquide volatil, une mémoire volatile). Un volatile (nom) = un oiseau." },
  { n:"R323", th:"conf", t:"vu et vue",
    e:"Vu, invariable devant le nom, = étant donné : vu les circonstances ; au vu de ces faits ; au vu et au su de tous ; un déjà-vu. La vue = le sens, le panorama : en vue de (= dans le but de), à vue d'œil, à première vue." },

  /* ---------- Mots et expressions condamnés ---------- */
  { n:"R235", th:"cond", t:"loin s'en faut",
    e:"« Loin s'en faut » est un croisement fautif de « loin de là » et de « tant s'en faut ». On choisit l'une ou l'autre tournure, ou « il s'en faut de beaucoup » : il n'est pas riche, tant s'en faut." },
  { n:"R83", th:"cond", t:"malgré que",
    e:"« malgré que » est critiqué : employez « bien que » ou « quoique » + subjonctif. Seul tour admis (littéraire) : malgré qu'il en ait (= malgré lui)." },
  { n:"R236", th:"cond", t:"solutionner",
    e:"« Solutionner » est critiqué : on emploie résoudre (résoudre un problème, une énigme), régler (un litige) ou surmonter (une difficulté). « Pallier » ne convient pas : il signifie atténuer provisoirement, non résoudre." },
  { n:"R222", th:"cond", t:"les pléonasmes grammaticaux",
    e:"Évitez les doublons : « dont… en » (le livre dont j'en parle ✗), « où… y » (la ville où j'y vis ✗), « dont… son » (l'auteur dont j'aime son style ✗), « que… le ». Dites : le livre dont je parle, l'auteur dont j'aime le style." },
  { n:"R324", th:"cond", t:"au jour d'aujourd'hui, en une heure de temps…",
    e:"Pléonasmes à éviter : au jour d'aujourd'hui (aujourd'hui signifie déjà « au jour de ce jour », hui venant du latin hodie), en une heure de temps (une heure est une durée), sur un même pied d'égalité. Dites : aujourd'hui, en une heure, sur un pied d'égalité." },
  { n:"R325", th:"cond", t:"autrement plus, voire même",
    e:"« autrement plus » (autrement suffit : c'est autrement difficile) et « voire même » (voire = et même) sont des renforcements pléonastiques critiqués." },
  { n:"R326", th:"cond", t:"collaborer ensemble, s'entraider mutuellement, opposer son veto",
    e:"Collaborer, coopérer, s'entraider contiennent déjà l'idée d'ensemble ou de réciprocité : on collabore, on s'entraide, sans « ensemble » ni « mutuellement ». En revanche, « opposer son veto », parfois critiqué, est admis par les dictionnaires, comme « mettre son veto »." },
  { n:"R327", th:"cond", t:"mineurs de moins de dix-huit ans, panacée universelle",
    e:"Un mineur a, par définition, moins de dix-huit ans ; une panacée est, par définition, un remède universel. Dites : les mineurs, une panacée. En revanche, « les mineurs de moins de quinze ans » est correct, car l'âge précisé est inférieur à dix-huit ans." },
  { n:"R328", th:"cond", t:"tous sont unanimes",
    e:"L'unanimité suppose déjà la totalité : dites « ils sont unanimes » (et non « tous unanimes »), ou « tous sont d'accord »." },
];
